const tw = (() => { try { return require("tailwindcss"); } catch (e) { console.error("ERROR: cannot load tailwindcss: " + e.message); process.exit(2); } })();
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const compiler = await tw.compile("@theme { --spacing: 0.25rem; }\n@tailwind utilities;");
  const out = compiler.build(["m-1"]);
  const m = /\.m-1\s*\{\s*margin:\s*([^;}]+?)\s*;?\s*\}/.exec(out);
  if (!m) broken("no .m-1 rule in output: " + out);
  if (m[1] === "calc(var(--spacing) * 1)") symptom("m-1 generates margin: calc(var(--spacing) * 1)");
  if (m[1] !== "var(--spacing)") broken("m-1 generates margin: " + m[1]);
  console.log("OK: m-1 generates margin: var(--spacing)");
})().catch(e => broken(String(e && e.message)));

